#include <iostream>
#include <vector>
#include <cmath>

int main() {
    std::vector<long long> l(2);
    for (int i = 0; i < 2; ++i) {
        std::cin >> l[i];
    }
    long long p = l[0];
    long long k = l[1];
    long long mmod = 1000000007;

    if (k == 0) {
        long long result = 1;
        long long base = p % mmod;
        long long exp = p - 1;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mmod;
            base = (base * base) % mmod;
            exp >>= 1;
        }
        std::cout << result << std::endl;
    } else if (k == 1) {
        long long result = 1;
        long long base = p % mmod;
        long long exp = p;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mmod;
            base = (base * base) % mmod;
            exp >>= 1;
        }
        std::cout << result << std::endl;
    } else {
        long long x = 1;
        long long i;
        for (i = 1; i <= p; ++i) {
            x = (x * k) % p;
            if (x == 1) {
                break;
            }
        }
        long long exponent = (p - 1) / i;
        long long result = 1;
        long long base = p % mmod;
        long long exp = exponent;
        while (exp > 0) {
            if (exp & 1) result = (result * base) % mmod;
            base = (base * base) % mmod;
            exp >>= 1;
        }
        std::cout << result << std::endl;
    }
    return 0;
}
